return [
  {
    json: {
      messageId: 'sample-routine-001',
      channel: 'web_chat',
      name: 'Lena Ortiz',
      message: 'Can you explain which apps you can connect for a weekly report?',
      customerRequestedHuman: false,
      containsSensitiveData: false,
      existingOpenCase: false
    }
  },
  {
    json: {
      messageId: 'sample-human-002',
      channel: 'whatsapp',
      name: 'Marcus Reed',
      message: 'I need a person. A charge looks wrong and this is urgent.',
      customerRequestedHuman: true,
      containsSensitiveData: false,
      existingOpenCase: true
    }
  }
];

const humanTerms = ['human', 'person', 'someone', 'call me', 'agent'];
const reviewTerms = ['urgent', 'asap', 'complaint', 'charge', 'billing', 'refund', 'security', 'password', 'legal'];

return $input.all().map((item) => {
  const source = item.json;
  const message = String(source.message || '').trim();
  const lower = message.toLowerCase();
  const reasons = [];
  const matchedHumanTerms = humanTerms.filter((term) => lower.includes(term));
  const matchedReviewTerms = reviewTerms.filter((term) => lower.includes(term));

  if (Boolean(source.customerRequestedHuman) || matchedHumanTerms.length > 0) {
    reasons.push('Customer requested a person');
  }
  if (Boolean(source.containsSensitiveData)) {
    reasons.push('Message is marked as containing sensitive data');
  }
  if (Boolean(source.existingOpenCase)) {
    reasons.push('An open case already exists');
  }
  if (matchedReviewTerms.length > 0) {
    reasons.push(`Review topic detected: ${matchedReviewTerms.join(', ')}`);
  }
  if (!message) {
    reasons.push('Message text is missing');
  }

  return {
    json: {
      messageId: String(source.messageId || ''),
      channel: String(source.channel || '').trim(),
      name: String(source.name || '').trim(),
      message,
      matchedHumanTerms,
      matchedReviewTerms,
      handoffReasons: reasons,
      requiresHumanReview: reasons.length > 0
    }
  };
});
